<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { ElDialog } from 'element-plus'
import AppSelect from '@/components/AppSelect.vue'
import { api } from '@/api'
import { tr } from '@/i18n'
import { notice } from '@/shared/notice'
import { catalogApi, type CatalogResource } from './catalog'
import type { Asset, AssetVariant, Novel } from '@/types'
import { useAuthStore } from '@/features/auth/authStore'
const props=defineProps<{item:CatalogResource|null}>(),emit=defineEmits<{close:[]}>()
const auth=useAuthStore(),projects=ref<Novel[]>([]),project=ref(''),assets=ref<Asset[]>([]),asset=ref(''),variants=ref<AssetVariant[]>([]),variant=ref(''),busy=ref(false),loading=ref(false),error=ref(''),name=ref(''),targetsLoading=ref(false),variantsLoading=ref(false)
let epoch=0,projectLoad=0,variantLoad=0
const title=computed(()=>props.item?.kind==='voice'?tr('绑定角色或旁白'):tr('用于项目'))
watch(()=>[props.item?.key,auth.activeTeamId],async()=>{const version=++epoch;++projectLoad;++variantLoad;name.value=props.item?.name||'';project.value='';asset.value='';variants.value=[];variant.value='';projects.value=[];assets.value=[];error.value='';busy.value=false;targetsLoading.value=false;variantsLoading.value=false;if(!props.item)return;loading.value=true;try{const result=await catalogApi.projects();if(version===epoch)projects.value=result.data.items}catch(reason){if(version===epoch)error.value=reason instanceof Error?reason.message:tr('项目加载失败')}finally{if(version===epoch)loading.value=false}},{immediate:true})
watch(project,async value=>{const version=++projectLoad;++variantLoad;asset.value='';variants.value=[];variant.value='';assets.value=[];targetsLoading.value=false;if(!value||props.item?.kind!=='voice')return;targetsLoading.value=true;try{const result=await catalogApi.projectCharacters(Number(value));if(version===projectLoad)assets.value=result.data.items.filter(row=>row.asset_type===1)}catch(reason){if(version===projectLoad)error.value=String(reason)}finally{if(version===projectLoad)targetsLoading.value=false}})
watch(asset,async value=>{const version=++variantLoad;variant.value='';variants.value=[];variantsLoading.value=false;if(!value)return;variantsLoading.value=true;try{const result=await api.assetVariants(Number(value));if(version===variantLoad)variants.value=result.data}catch(reason){if(version===variantLoad)error.value=String(reason)}finally{if(version===variantLoad)variantsLoading.value=false}})
async function apply(){if(!props.item||!project.value||busy.value||targetsLoading.value||variantsLoading.value)return;const version=epoch;busy.value=true;error.value='';try{await catalogApi.apply(props.item.key,Number(project.value),asset.value?Number(asset.value):undefined,variant.value?Number(variant.value):undefined,undefined,props.item.kind==='character'||props.item.catalog==='asset'?name.value.trim():undefined);if(version===epoch){notice.success(tr('已应用到项目'));emit('close')}}catch(reason){if(version===epoch)error.value=reason instanceof Error?reason.message:tr('应用失败')}finally{if(version===epoch)busy.value=false}}
onBeforeUnmount(()=>{++epoch;++projectLoad;++variantLoad})
</script>
<template><ElDialog class="resource-library-dialog" :model-value="!!item" :title="title" width="460px" append-to-body @close="emit('close')"><form class="catalog-apply" @submit.prevent="apply"><strong>{{item?.name}}</strong><label>{{tr('目标项目')}}<AppSelect v-model="project" :options="[{value:'',label:tr('请选择项目')},...projects.map(row=>({value:String(row.id),label:row.name}))]" :ariaLabel="tr('目标项目')" :disabled="loading||busy" :menu-z-index="3000" /></label><label v-if="item?.kind==='character'||item?.catalog==='asset'">{{tr('资产名称')}}<input v-model="name" maxlength="100" required :disabled="busy"/></label><template v-if="item?.kind==='voice'"><label>{{tr('绑定对象')}}<AppSelect v-model="asset" :options="[{value:'',label:tr('项目旁白')},...assets.map(row=>({value:String(row.id),label:row.canonical_name}))]" :ariaLabel="tr('绑定对象')" :disabled="busy||targetsLoading" :menu-z-index="3000" /></label><label v-if="asset">{{tr('形态')}}<AppSelect v-model="variant" :options="[{value:'',label:tr('主形象')},...variants.map(row=>({value:String(row.id),label:row.name}))]" :ariaLabel="tr('形态')" :disabled="busy||variantsLoading" :menu-z-index="3000" /></label></template><p>{{tr('资源可在该项目中继续使用，不自动启动生成。')}}</p><p v-if="error" role="alert">{{error}}</p><AppButton type="submit" variant="primary" :loading="busy" :disabled="!project||busy||loading||targetsLoading||variantsLoading">{{tr('确认选择')}}</AppButton></form></ElDialog></template>
<style scoped>.catalog-apply{display:grid;gap:17px;color:var(--app-text)}label{display:grid;gap:8px}input{min-width:0;width:100%;height:38px;color:inherit;background:var(--app-surface);border:1px solid var(--app-border);border-radius:7px;padding:0 8px}p{font-size:12px;color:var(--app-text-secondary);line-height:1.7}[role=alert]{color:var(--app-danger)}</style>
